    #include <bits/stdc++.h>
using namespace std;

// Function to compute gcd using Euclidean Algorithm
int gcd(int a, int b)
{
    if (b == 0)
        return a;
    return gcd(b, a % b);
}

// Function to compute lcm using gcd
// Using (a / gcd) * b to avoid overflow
int lcm(int a, int b)
{
    return (a / gcd(a, b)) * b;
}

class SegmentTree
{
  private:
    vector<int> tree;
    vector<int> arr;
    int n;

  public:
    SegmentTree(vector<int> input)
    {
        arr = input;
        n = arr.size();
        tree.resize(4 * n);
        build(1, 0, n - 1);
    }

    // Build the segment tree
    void build(int node, int start, int end)
    {
        // Leaf node
        if (start == end)
        {
            tree[node] = arr[start];
            return;
        }

        int mid = (start + end) / 2;

        // Build left and right subtree
        build(2 * node, start, mid);
        build(2 * node + 1, mid + 1, end);

        // Merge step: store LCM of children
        tree[node] = lcm(tree[2 * node], tree[2 * node + 1]);
    }

    // Update value at index idx to val
    void update(int node, int start, int end, int idx, int val)
    {
        // Leaf node
        if (start == end)
        {
            arr[idx] = val;
            tree[node] = val;
            return;
        }

        // find mid
        int mid = (start + end) / 2;

        // Recurse to correct side
        if (idx <= mid)
            update(2 * node, start, mid, idx, val);
        else
            update(2 * node + 1, mid + 1, end, idx, val);

        // Update current node after child update
        tree[node] = lcm(tree[2 * node], tree[2 * node + 1]);
    }

    // Query LCM in range [l, r]
    int query(int node, int start, int end, int l, int r)
    {
        // Completely outside range
        // Return 1 (identity for LCM)
        if (end < l || start > r)
            return 1;

        // Completely inside range
        if (l <= start && end <= r)
            return tree[node];

        // Partial overlap
        int mid = (start + end) / 2;

        int left = query(2 * node, start, mid, l, r);
        int right = query(2 * node + 1, mid + 1, end, l, r);

        return lcm(left, right);
    }
};

// function to find range lcm query
vector<int> RangeLCMQuery(vector<int> &arr, vector<vector<int>> &queries)
{
    SegmentTree st(arr);

    vector<int> result;

    for (auto &q : queries)
    {
        int type = q[0];

        if (type == 1)
        {
            int idx = q[1];
            int val = q[2];

            // Perform update
            st.update(1, 0, arr.size() - 1, idx, val);
        }
        else
        {
            int l = q[1];
            int r = q[2];

            // Perform query
            int ans = st.query(1, 0, arr.size() - 1, l, r);
            result.push_back(ans);
        }
    }

    return result;
}

int main()
{
    vector<int> arr = {2, 3, 4, 6, 8, 16};

    // Queries:
    // {type, x, y}
    // type 1 → update index x with value y
    // type 2 → query LCM in range [x, y]
    vector<vector<int>> queries = {{2, 0, 2}, {1, 3, 8}, {2, 2, 5}};

    vector<int> res = RangeLCMQuery(arr, queries);

    // Print results
    for (int x : res)
        cout << x << " ";

    return 0;
}


